PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS newsletter_subscribers(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE,email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','paused','unsubscribed','suppressed')),personalization_enabled INTEGER NOT NULL DEFAULT 1 CHECK(personalization_enabled IN(0,1)),subscribed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,unsubscribed_at TEXT,last_email_sent_at TEXT,last_email_open_at TEXT,last_email_click_at TEXT,last_site_activity_at TEXT,engagement_state TEXT NOT NULL DEFAULT 'active' CHECK(engagement_state IN('very_active','active','inactive','dormant','reactivating')),reactivated_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_newsletter_subscribers_status_activity ON newsletter_subscribers(status,last_site_activity_at);
CREATE TABLE IF NOT EXISTS user_interests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,entity_type TEXT NOT NULL CHECK(entity_type IN('category','topic','brand','product','game','platform')),entity_key TEXT NOT NULL,score REAL NOT NULL DEFAULT 0,interaction_count INTEGER NOT NULL DEFAULT 0,last_interaction_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,entity_type,entity_key));
CREATE INDEX IF NOT EXISTS idx_user_interests_user_score ON user_interests(user_id,score DESC,last_interaction_at DESC);
CREATE TABLE IF NOT EXISTS newsletter_campaigns(id TEXT PRIMARY KEY,article_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','segmenting','queued','sending','completed','cancelled','failed')),subject TEXT NOT NULL,audience_count INTEGER NOT NULL DEFAULT 0,queued_count INTEGER NOT NULL DEFAULT 0,sent_count INTEGER NOT NULL DEFAULT 0,delivered_count INTEGER NOT NULL DEFAULT 0,opened_count INTEGER NOT NULL DEFAULT 0,clicked_count INTEGER NOT NULL DEFAULT 0,bounced_count INTEGER NOT NULL DEFAULT 0,complained_count INTEGER NOT NULL DEFAULT 0,unsubscribed_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,started_at TEXT,completed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_newsletter_campaigns_created ON newsletter_campaigns(created_at DESC);
CREATE TABLE IF NOT EXISTS newsletter_deliveries(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES newsletter_campaigns(id) ON DELETE CASCADE,user_id TEXT NOT NULL,email TEXT NOT NULL,ses_message_id TEXT,relevance_score REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','sending','sent','delivered','opened','clicked','soft_bounce','hard_bounce','complained','unsubscribed','failed')),attempt_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,sent_at TEXT,delivered_at TEXT,opened_at TEXT,clicked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(campaign_id,user_id));
CREATE INDEX IF NOT EXISTS idx_newsletter_deliveries_message ON newsletter_deliveries(ses_message_id);
CREATE INDEX IF NOT EXISTS idx_newsletter_deliveries_campaign_status ON newsletter_deliveries(campaign_id,status);
CREATE TABLE IF NOT EXISTS email_events(id TEXT PRIMARY KEY,dedupe_key TEXT NOT NULL UNIQUE,delivery_id TEXT,campaign_id TEXT,user_id TEXT,ses_message_id TEXT,event_type TEXT NOT NULL,url TEXT,is_bot INTEGER NOT NULL DEFAULT 0,user_agent TEXT,occurred_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_email_events_campaign_type ON email_events(campaign_id,event_type,occurred_at DESC);
